// fael — generated by `fael install`; rewritten on every install, edit fael instead.
// Maps OpenCode to the neutral hook protocol (docs/integrate.md): spawn
// `fael hook <event>`, Event JSON on stdin, Reply JSON on stdout. Never throws.
//
// Two clients read this file, because OpenCode 2 replaced its plugin API and a
// V1 plugin does not load there at all. `Fael` (named export) returns V1 hooks
// and is what OpenCode 1 calls; the default export is the V2 definition, whose
// `setup` registers each hook on the domain that owns the operation. Keep both
// in step when an event changes. Nothing here imports `@opencode/plugin`: the
// V2 loader validates `{ id, setup }` on its own, and a V1 runtime cannot
// resolve that specifier.
import { spawnSync } from "node:child_process";

const FAEL = __FAEL__;

function hook(event, e) {
  try {
    const r = spawnSync(FAEL, ["hook", event], {
      input: JSON.stringify({ ...e, client: "opencode" }),
      encoding: "utf-8",
      timeout: 5000,
    });
    return JSON.parse(r.stdout || "{}");
  } catch {
    return {};
  }
}

// Tool names both clients use: V1 (`bash`, `apply_patch`, `filePath`) and V2
// (`shell`, `patch`, `path`). `fael` matches shell names case-insensitively and
// knows both, so one set covers the two.
const EDIT = new Set(["edit", "write", "patch", "apply_patch"]);
const SEARCH = new Set(["grep", "glob", "shell", "bash"]);
// shell tools only, so the shell env below never picks a grep's session
const SHELL = new Set(["shell", "bash"]);

// patch carries no file path: read the paths off the patch headers, the same
// four claude.rs `patch_files` reads for Codex.
const PATCH_HEADERS = [
  "*** Add File: ",
  "*** Update File: ",
  "*** Delete File: ",
  "*** Move to: ",
];
function patch_files(patch) {
  if (typeof patch !== "string") return [];
  return patch
    .split("\n")
    .flatMap((l) => {
      const h = PATCH_HEADERS.find((h) => l.startsWith(h));
      return h ? [l.slice(h.length).trim()] : [];
    })
    .filter(Boolean);
}

// the file a tool call touched: V2 names it `path`, V1 `filePath`
const paths = (tool, input) =>
  tool === "patch" || tool === "apply_patch"
    ? patch_files(input?.patchText)
    : [input?.path ?? input?.filePath].filter(Boolean);

// Assistant text for the idle reader, kept in step with hook/opencode.rs
// v1_stop/v2_stop: V1 messages carry parts[], V2 content[]; text is every
// assistant text joined, reply the last assistant message only; anything
// missing or non-string is "" — idle never answers with a prompt.
const texts_of = (m, key) =>
  ((m?.[key] ?? []).filter((p) => p?.type === "text").map((p) => (typeof p.text === "string" ? p.text : "")));
const stop_texts = (messages, v1) => {
  const asked = (messages ?? []).filter((x) => (v1 ? x?.info?.role === "assistant" : x?.type === "assistant"));
  const key = v1 ? "parts" : "content";
  const text = asked.flatMap((x) => texts_of(x, key)).join("\n");
  const last = asked[asked.length - 1];
  return { text, reply: last ? texts_of(last, key).join("\n") : "" };
};

// A sub-agent is a child session: parentID names its parent, root sessions
// carry none (measured: `session export` info lists no parentID on roots;
// the server binary indexes `parent_id` and documents "a parentID creates a
// linked child session at its parent's location"). The child keeps its own
// session string — its own seen list — and sends agent=<root> on stop only,
// so hook/stop.rs takes the subagent branch (cited ids, no bug-rule stash
// orphaned under the short-lived child key, no per-turn receipt). Tool
// results and the brief stay agent-less, so the push, the seen list and the
// prompt pointer keep one key.
const parent_of = (s) =>
  s?.parentID ?? s?.parentId ?? s?.parent_id ?? s?.info?.parentID ?? s?.data?.parentID ?? null;
// of a served session resolves to its root; a foreign session resolves to
// null once, then stays cached
const root_of = async (id, starts, parents, get) => {
  let cur = id;
  for (let i = 0; i < 5 && cur; i++) {
    let p = parents.get(cur);
    if (p === undefined) {
      try {
        p = parent_of(await get(cur));
      } catch {
        p = null;
      }
      parents.set(cur, p ?? null);
    }
    if (p == null) return starts.has(cur) ? cur : null;
    cur = p;
  }
  return null;
};

// `session.status` replaced `session.idle`; both say the turn ended.
const idle = (event) =>
  event.type === "session.idle" || (event.type === "session.status" && event.data?.status?.type === "idle");

// Append fael's push to what the model reads. A failed tool has nothing to
// append to, and V2 hands the hook its result as content parts.
function append(event, text) {
  if (!text || event.status !== "completed" || !event.result) return;
  const content = event.result.content;
  if (Array.isArray(content)) content.push({ type: "text", text });
  else if (typeof content === "string") event.result.content = `${content}\n\n${text}`;
  else event.result.content = [{ type: "text", text }];
}

// A session's start time: V1 hands epoch millis, V2 is typed as millis but
// decodes a `DateTime` in some builds — read the field it carries.
const epoch = (v) => {
  const n = typeof v === "number" ? v : typeof v === "string" ? Date.parse(v) : v?.epochMillis;
  return Number.isFinite(n) ? n : undefined;
};

// OpenCode 1: a function returning hooks, one object with a key per event.
export const Fael = async ({ client, directory }) => {
  // session start as RFC 3339 — the `session` string stop needs, and the same
  // string edit sends so both key one edit list
  const starts = new Map();
  const parents = new Map();
  const start = async (id) => {
    if (!starts.has(id)) {
      let t = Date.now();
      let p = null;
      try {
        const s = await client.session.get({ path: { id } });
        t = s.data?.time?.created ?? t;
        p = parent_of(s.data) ?? null;
      } catch {}
      starts.set(id, new Date(t).toISOString());
      parents.set(id, p);
    }
    return starts.get(id);
  };
  const briefs = new Map();
  // the user line (Reply.notice) goes to a toast, never into the agent's
  // context; an OpenCode without the toast API simply shows nothing
  const say = (r) => {
    try {
      if (r.notice) client.tui?.showToast?.({ body: { message: r.notice, variant: "info" } })?.catch?.(() => {});
    } catch {}
  };

  return {
    // system is rebuilt per LLM call: fetch the brief once, push it every call
    "experimental.chat.system.transform": async (input, output) => {
      const id = input?.sessionID;
      if (!id) return;
      if (!briefs.has(id)) {
        const r = hook("session-start", { cwd: directory, session: await start(id) });
        say(r);
        briefs.set(id, r.context ?? "");
      }
      if (briefs.get(id)) output.system.push(briefs.get(id));
    },

    // bash tool env: OpenCode exports no session id to the shell, so hand
    // `fael add` its hook session (the same RFC 3339 `start(id)` string the
    // usage lines use) via FAEL_SESSION. PTY shells carry no sessionID — no-op.
    "shell.env": async (input, output) => {
      const id = input?.sessionID;
      if (!id) return;
      try {
        output.env ??= {};
        output.env.FAEL_SESSION = await start(id);
      } catch {}
    },

    "tool.execute.after": async (input, output) => {
      const session = await start(input.sessionID);
      if (SEARCH.has(input.tool)) {
        // grep/glob/bash reads push like a shell read: the raw call goes to
        // `fael hook search`, which resolves the touched files server-side
        const r = hook("search", {
          cwd: directory,
          session,
          tool: input.tool,
          tool_input: input.args ?? {},
          tool_response: output?.output ?? output ?? {},
        });
        if (r.context) output.output += `\n\n${r.context}`;
        say(r);
        return;
      }
      const event = input.tool === "read" ? "read" : EDIT.has(input.tool) ? "edit" : null;
      const files = paths(input.tool, input.args);
      if (!event || files.length === 0) return;
      const r = hook(event, { cwd: directory, session, files });
      if (r.context) output.output += `\n\n${r.context}`;
      say(r);
    },

    // OpenCode has no Stop hook: on idle the last message goes to fael, which
    // files its cited ids and never answers with a prompt — one would start
    // a turn the user cannot cancel with Esc. A child session (sub-agent)
    // sends agent=<root>, so stop takes the subagent branch; a session no
    // ancestor of which this instance served is foreign — skip it.
    event: async ({ event }) => {
      const id = event.properties?.sessionID;
      if (typeof id !== "string") return;
      // compaction dropped the pushed rows from context: `source: "compact"`
      // makes fael forget what it said there, so the next read tells them again
      if (event.type === "session.compacted") {
        const root = await root_of(id, starts, parents, (x) => client.session.get({ path: { id: x } }));
        if (!root) return;
        const e = { cwd: directory, session: await start(id), source: "compact" };
        briefs.set(id, hook("session-start", e).context ?? "");
        return;
      }
      if (event.type !== "session.idle") return;
      const root = await root_of(id, starts, parents, (x) => client.session.get({ path: { id: x } }));
      if (!root) return;
      let text = "";
      let reply = "";
      try {
        const m = await client.session.messages({ path: { id } });
        ({ text, reply } = stop_texts(m.data, true));
      } catch {}
      const r = hook("stop", {
        cwd: directory,
        session: await start(id),
        text,
        reply,
        ...(root !== id ? { agent: root } : {}),
      });
      say(r);
    },
  };
};

// OpenCode 2: `setup(ctx)` registers every hook on the domain that owns the
// operation. Its context is the server client, so `ctx.session`, `ctx.tool`,
// `ctx.shell` and `ctx.event` replace the V1 `client` and the returned hook map.
export default {
  id: "fael",
  async setup(ctx) {
    const directory = ctx.location.directory;

    // session start as RFC 3339 — the `session` string read/edit/search/stop
    // need, and the same string edit sends so both key one edit list
    const starts = new Map();
    const parents = new Map();
    const start = async (id) => {
      if (!starts.has(id)) {
        let t = Date.now();
        let p = null;
        try {
          const s = await ctx.session.get({ sessionID: id });
          const created = epoch(s?.time?.created);
          if (created) t = created;
          p = parent_of(s) ?? null;
        } catch {}
        starts.set(id, new Date(t).toISOString());
        parents.set(id, p);
      }
      return starts.get(id);
    };
    const briefs = new Map();

    // system is rebuilt per model request: fetch the brief once, push it every
    // request. Only the agent loop runs this hook, so it is not registered for
    // compaction — that event re-arms the brief instead (below). The gate is
    // `briefs`, never `starts`: a tool hook that ran first (start() keys the
    // session string) would otherwise leave the session without a brief.
    await ctx.session.hook("context", async (event) => {
      const id = event.sessionID;
      if (!id) return;
      if (!briefs.has(id)) {
        briefs.set(id, hook("session-start", { cwd: directory, session: await start(id) }).context ?? "");
      }
      const brief = briefs.get(id);
      if (brief) event.system.push({ type: "text", text: brief });
    });

    // Prompt admission: fire `fael hook prompt` with the user's text so the
    // open-key pointer line works here too. Runs once per admission, never
    // before every model call — and it only edits the admitted text, never
    // starts a turn of its own (no session.prompt/generate call). The
    // once-per-session rule lives server-side in `prompt.rs`; a repeated
    // admission (retry, concurrent submit) gets an empty reply and appends
    // nothing. V1 has no equivalent: its `chat.message` payload is
    // unverified against a V1 runtime, so V1 stays without the hint.
    await ctx.session.hook("prompt", async (event) => {
      const id = event.sessionID;
      const text = event.prompt?.text;
      if (!id || !text) return;
      const r = hook("prompt", { cwd: directory, session: await start(id), text });
      if (r.context) event.prompt.text += `\n\n${r.context}`;
    });

    // V2's shell event carries no session id (command/cwd/timeout/shell/env),
    // so hand `fael add` the session of the shell tool call being run: the tool
    // hook saw it a moment earlier. Only while exactly one session runs a shell
    // — a guess would tag another session's row.
    const shells = new Map();
    await ctx.tool.hook("execute.before", (event) => {
      if (SHELL.has(event.tool)) shells.set(event.sessionID, Date.now());
    });
    await ctx.shell.hook("create.before", async (event) => {
      const now = Date.now();
      for (const [id, at] of shells) if (now - at > 5000) shells.delete(id);
      if (shells.size !== 1) return;
      try {
        event.env.FAEL_SESSION = await start([...shells.keys()][0]);
      } catch {}
    });

    await ctx.tool.hook("execute.after", async (event) => {
      const session = await start(event.sessionID);
      if (SEARCH.has(event.tool)) {
        // grep/glob/shell reads push like a shell read: the raw call goes to
        // `fael hook search`, which resolves the touched files server-side
        const r = hook("search", {
          cwd: directory,
          session,
          tool: event.tool,
          tool_input: event.input ?? {},
          tool_response: event.status === "completed" ? (event.result ?? {}) : (event.error ?? {}),
        });
        append(event, r.context);
        return;
      }
      const name = event.tool === "read" ? "read" : EDIT.has(event.tool) ? "edit" : null;
      const files = paths(event.tool, event.input);
      if (!name || files.length === 0) return;
      const r = hook(name, { cwd: directory, session, files });
      append(event, r.context);
    });

    // OpenCode has no Stop hook: on idle the last message goes to fael, which
    // files its cited ids and never answers with a prompt — one would start
    // a turn the user cannot cancel with Esc. V2 has no toast surface for a
    // server plugin, so the user line (Reply.notice) is dropped. A child
    // session (sub-agent) sends agent=<root>, so stop takes the subagent
    // branch; the server-wide stream carries every session, so one no
    // ancestor of which was served here is foreign — skip it.
    const controller = new AbortController();
    void (async () => {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        const id = event?.data?.sessionID;
        if (typeof id !== "string") continue;
        if (!idle(event) && event.type !== "session.compacted") continue;
        // the tool hook may never have seen this child itself: resolve the
        // serving root through the cached parent chain (one fetch per unknown
        // id at most) — hot paths above never fetch
        const root = await root_of(id, starts, parents, (x) => ctx.session.get({ sessionID: x }));
        if (!root) continue;
        // compaction dropped the pushed rows from context: `source: "compact"`
        // makes fael forget what it said there, so the next read tells them again
        if (event.type === "session.compacted") {
          const e = { cwd: directory, session: await start(id), source: "compact" };
          briefs.set(id, hook("session-start", e).context ?? "");
          continue;
        }
        let text = "";
        let reply = "";
        try {
          ({ text, reply } = stop_texts(await ctx.session.context({ sessionID: id }), false));
        } catch {}
        hook("stop", {
          cwd: directory,
          session: await start(id),
          text,
          reply,
          ...(root !== id ? { agent: root } : {}),
        });
      }
    })().catch(() => {});
    return () => controller.abort();
  },
};
